import json,os,signal,socket,subprocess,time,urllib.request
from pathlib import Path
root=Path(__file__).resolve().parents[1]
env={k:v for k,v in os.environ.items() if not k.startswith('WAR_')}
for row in (root/'deploy/war-relay-100k.env.example').read_text().splitlines():
 if row and not row.startswith('#'):
  key,value=row.split('=',1);env[key]=value
ports=[]
while len(ports)<2:
 with socket.socket() as sock:sock.bind(('127.0.0.1',0));port=sock.getsockname()[1]
 if port not in ports:ports.append(port)
env.update(WAR_BIND=f'127.0.0.1:{ports[0]}',WAR_ADMIN_BIND=f'127.0.0.1:{ports[1]}')
record={'profile':'deploy/war-relay-100k.env.example','profile_values':{k:v for k,v in env.items() if k.startswith('WAR_')},'passed':False}
with (root/'artifacts/capacity-profile-startup.log').open('w+') as log:
 process=subprocess.Popen([str(root/'artifacts/baselines/capacity-final/war-relay')],env=env,stdout=log,stderr=log)
 try:
  deadline=time.monotonic()+5
  while True:
   assert process.poll() is None
   try:
    with urllib.request.urlopen(f'http://127.0.0.1:{ports[1]}/readyz',timeout=1) as response:assert response.status==200
    break
   except OSError:
    assert time.monotonic()<deadline;time.sleep(.02)
  with urllib.request.urlopen(f'http://127.0.0.1:{ports[1]}/metrics') as response:record['metrics']=response.read().decode()
  assert 'war_read_buffer_limit_bytes 268435456' in record['metrics']
  process.send_signal(signal.SIGTERM);record['exit_code']=process.wait(timeout=5);assert record['exit_code']==0
  record['passed']=True
 finally:
  if process.poll() is None:process.terminate();process.wait(timeout=5)
record['verification_source']=Path(__file__).read_text()
(root/'artifacts/capacity-profile-startup.json').write_text(json.dumps(record,indent=2)+'\n')
unit=(root/'deploy/war-relay.service').read_text().replace('/usr/local/bin/war-relay',str(root/'artifacts/baselines/capacity-final/war-relay'))
unit+='\n'+'\n'.join(row for row in (root/'deploy/war-relay-100k.conf.example').read_text().splitlines() if not row.startswith('#'))+'\n'
(root/'artifacts/war-relay-capacity-validation.service').write_text(unit)
print(json.dumps({'passed':record['passed'],'receive_request':env['WAR_TCP_RECEIVE_BUFFER_BYTES']}))
